% title      : Automatically generated logs
:- pred logs_under_control/2, gloss('logs of high-risk AI system under control of provider'), source('reconciled').
:- pred automatically_generated/1, gloss('logs automatically generated by the high-risk AI system as referred to in Article 19'), source('reconciled').
:- pred high_risk_ai_system/1, gloss('AI system listed in Annex III as high-risk'), source('reconciled').
:- pred provider/1, gloss('entity that develops or places an AI system'), source('reconciled').
:- pred financial_institution/1, gloss('financial institution subject to Union financial services law'), source('celex:32024R1689/oj#art_19').
:- pred subject_to_financial_services_law/1, gloss('subject to requirements regarding internal governance, arrangements or processes under Union financial services law'), source('celex:32024R1689/oj#art_19').
:- pred keep_logs/2, gloss('provider keeps logs for a period'), source('celex:32024R1689/oj#art_19').
:- pred appropriate_period/2, gloss('period appropriate to intended purpose of high-risk AI system'), source('celex:32024R1689/oj#art_19').
:- pred minimum_period/1, gloss('minimum period of six months'), source('celex:32024R1689/oj#art_19').
:- pred logs_as_part_of_financial_documentation/1, gloss('logs maintained as part of documentation kept under relevant financial services law'), source('celex:32024R1689/oj#art_19').

must_keep_logs(Provider, S) :-
    provider(Provider),
    high_risk_ai_system(S),
    logs_under_control(Provider, S),
    automatically_generated(S).

keep_logs(Provider, S) :-
    must_keep_logs(Provider, S),
    appropriate_period(Period, S),
    minimum_period(Period).

appropriate_period(Period, S) :-
    intended_purpose(S),
    period_appropriate_to_intended_purpose(Period, S).

minimum_period(months(6)).

period_appropriate_to_intended_purpose(Period, S) :-
    intended_purpose(S),
    period_at_least(Period, months(6)).

period_at_least(Period, Minimum) :-
    Period = months(N),
    Minimum = months(M),
    N >= M.

logs_as_part_of_financial_documentation(Provider) :-
    provider(Provider),
    financial_institution(Provider),
    subject_to_financial_services_law(Provider),
    high_risk_ai_system(S),
    must_keep_logs(Provider, S).

must_keep_logs(Provider, S) :-
    provider(Provider),
    financial_institution(Provider),
    subject_to_financial_services_law(Provider),
    high_risk_ai_system(S),
    logs_as_part_of_financial_documentation(Provider).

provenance(must_keep_logs/2, 'celex:32024R1689/oj#art_19').
provenance(keep_logs/2, 'celex:32024R1689/oj#art_19').
